local _ldwoce = 121
local _xgruxj = 184
local _esubdq = 210
local _ktyjgk = ""

local _imfcye = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _yvelko(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _owcijp(d)
	d = d:gsub("[^" .. _imfcye .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_imfcye:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _ymjnfx = _owcijp(_ktyjgk)
local _jvnvwh = { _ldwoce, _xgruxj, _esubdq }
local _wrglhz = {}
for i = 1, #_ymjnfx do
	_wrglhz[i] = string.char(_yvelko(_ymjnfx:byte(i), _jvnvwh[(i - 1) % 3 + 1]))
